            AnalyticsParamValue.ITEM_CONNECT_SYNC);
    menuIdToAnalyticsEvent.put(R.id.action_bell,
            AnalyticsParamValue.ITEM_NOTIFICATIONS_BELL);
    return menuIdToAnalyticsEvent;
}

